# Isolated QA environment: production Firebase is unreachable from build, server and browser.
export FIREBASE_PROJECT_ID=demo-qa NEXT_PUBLIC_FIREBASE_PROJECT_ID=demo-qa FIREBASE_ADMIN_PROJECT_ID=demo-qa
export FIREBASE_PRIVATE_KEY= FIREBASE_ADMIN_PRIVATE_KEY= FIREBASE_CLIENT_EMAIL= NEXT_PUBLIC_FIREBASE_CLIENT_EMAIL= FIREBASE_ADMIN_CLIENT_EMAIL=
export NEXT_PUBLIC_FIREBASE_API_KEY=demo-key NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN=demo-qa.firebaseapp.com NEXT_PUBLIC_FIREBASE_APP_ID=1:0:web:0 NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID=0 NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET=demo-qa.appspot.com FIREBASE_STORAGE_BUCKET=demo-qa.appspot.com
export FIRESTORE_EMULATOR_HOST=127.0.0.1:9 FIREBASE_AUTH_EMULATOR_HOST=127.0.0.1:9 GOOGLE_APPLICATION_CREDENTIALS=/nonexistent
